import { Component } from 'react'
import PropTypes from 'prop-types'
import Modal from '../Modal'
import { LANG_STRINGS } from '../../lang'
import { LOGIN_AGENT_GOLD } from '../../images'
import CustomText from '../CustomText'
import { AgentColorPallette } from '../../configs/colorPallete'
import Button from '../Button'
import { DisplayFlexCCC } from '../../commonStyle/index.style'

class LoginInformationModal extends Component {
  static propTypes = {
    showModal: PropTypes.bool,
    agentName: PropTypes.string,
    onClose: PropTypes.func
  }

  render () {
    const { showModal, onClose, agentName } = this.props
    return (
      <Modal
        isOpen={showModal}
        onClose={onClose}
        heading={LANG_STRINGS.information}
      >
        <DisplayFlexCCC>
          <img src={LOGIN_AGENT_GOLD} alt='' />
          <CustomText top='10px' bottom='10px' size='18px' color={AgentColorPallette.black} weight={800}>
            {LANG_STRINGS.loginAsAgentSuccessful}
          </CustomText>
          <CustomText size='14px' bottom='10px' color={AgentColorPallette.black} textAlign='center'>
            {LANG_STRINGS.congretsSuccessfullyLogedInAs}&nbsp;
            <span className='golden-text'>{`"${agentName}"`}</span>
          </CustomText>
          <Button onClick={onClose}>
            {LANG_STRINGS.okay}
          </Button>
        </DisplayFlexCCC>
      </Modal>
    )
  }
}

export default LoginInformationModal
